doc = Document(str(SRC))

def norm(s):
    return ' '.join((s or '').replace('\xa0', ' ').split())

def find_para_starts(prefix):
    prefix = norm(prefix)
    for i, p in enumerate(doc.paragraphs):
        if norm(p.text).startswith(prefix):
            return i
    raise ValueError(f'Paragraph not found: {prefix}')

def delete_paragraph(paragraph):
    p = paragraph._element
    p.getparent().remove(p)
    p._p = p._element = None

def clear_between(start_text, end_text):
    start_idx = find_para_starts(start_text)
    end_idx = find_para_starts(end_text)
    for idx in range(end_idx - 1, start_idx, -1):
        delete_paragraph(doc.paragraphs[idx])
    return find_para_starts(start_text)

def set_paragraph_text(idx, text, align='justify', first_indent_cm=1.25):
    p = doc.paragraphs[idx]
    p.text = text
    if align == 'justify':
        p.alignment = 3
    elif align == 'left':
        p.alignment = 0
    elif align == 'center':
        p.alignment = 1
    p.paragraph_format.first_line_indent = Pt(first_indent_cm * 28.3465)
    p.paragraph_format.space_before = Pt(0)
    p.paragraph_format.space_after = Pt(0)
    for r in p.runs:
        r.font.name = 'Times New Roman'
        r.font.size = Pt(14)

def insert_paragraph_after(paragraph, text='', align='justify', first_indent_cm=1.25):
    new_p = deepcopy(paragraph._element)
    paragraph._element.addnext(new_p)
    new_para = None
    for p in doc.paragraphs:
        if p._element is new_p:
            new_para = p
            break
    if new_para is None:
        raise RuntimeError('Failed to insert paragraph')
    new_para.clear()
    if text:
        new_para.add_run(text)
    if align == 'justify':
        new_para.alignment = 3
    elif align == 'left':
        new_para.alignment = 0
    elif align == 'center':
        new_para.alignment = 1
    new_para.paragraph_format.first_line_indent = Pt(first_indent_cm * 28.3465)
    new_para.paragraph_format.space_before = Pt(0)
    new_para.paragraph_format.space_after = Pt(0)
    for r in new_para.runs:
        r.font.name = 'Times New Roman'
        r.font.size = Pt(14)
    return new_para

def insert_many_after(anchor_idx, items):
    last = doc.paragraphs[anchor_idx]
    for item in items:
        if item['type'] == 'body':
            last = insert_paragraph_after(last, item['text'], align='justify', first_indent_cm=1.25)
        elif item['type'] == 'left':
            last = insert_paragraph_after(last, item['text'], align='left', first_indent_cm=1.25)
        elif item['type'] == 'caption':
            last = insert_paragraph_after(last, item['text'], align='center', first_indent_cm=0)
    return last

def add_table_after(paragraph, intro, caption, rows, headers):
    p1 = insert_paragraph_after(paragraph, intro, align='justify', first_indent_cm=1.25)
    p2 = insert_paragraph_after(p1, caption, align='center', first_indent_cm=0)
    table = doc.add_table(rows=len(rows)+1, cols=len(headers))
    table.style = 'Table Grid'
    for c, h in enumerate(headers):
        table.cell(0, c).text = h
    for r, row in enumerate(rows, start=1):
        for c, val in enumerate(row):
            table.cell(r, c).text = val
    for row in table.rows:
        for cell in row.cells:
            for p in cell.paragraphs:
                p.alignment = 1
                p.paragraph_format.space_before = Pt(0)
                p.paragraph_format.space_after = Pt(0)
                for run in p.runs:
                    run.font.name = 'Times New Roman'
                    run.font.size = Pt(14)
    tbl_el = table._tbl
    p2._element.addnext(tbl_el)
    return insert_paragraph_after(p2, '', align='justify', first_indent_cm=1.25)

for p in doc.paragraphs:
    txt = p.text
    for old, new in [
        ('курсового проекта','дипломного проекта'), ('Курсового проекта','Дипломного проекта'),
        ('курсовой проект','дипломный проект'), ('Курсовой проект','Дипломный проект'),
        ('курсовая работа','дипломная работа'), ('Курсовая работа','дипломная работа')]:
        txt = txt.replace(old, new)
    if txt != p.text:
        p.text = txt
        for r in p.runs:
            r.font.name = 'Times New Roman'
            r.font.size = Pt(14)

